#!/usr/bin/env bash
# Verified baseline + checksum-guarded brand library. No credentials.
set -eu
zenith_build_tmp=$(mktemp -d /tmp/zenith-export-build.XXXXXX)
zenith_release_base=https://github.com/cenktepegoz/zenith-porcelain-render-test/releases/download
zenith_download() {
  curl -fsSL --retry 3 --connect-timeout 20 --max-time 300 "$1" -o "$zenith_build_tmp/$2"
  printf '%s  %s\n' "$3" "$zenith_build_tmp/$2" | sha256sum -c -
}
zenith_download "$zenith_release_base/seo-hardening-2026-09-17/zenith-porcelain-full-source-seo-hardening-2026-09-17.tar.gz" source.tar.gz 031a28b36378308d40065a833aa524898fb4b898e21f121bafb3798832bca75d
tar -xzf "$zenith_build_tmp/source.tar.gz"
zenith_download "$zenith_release_base/seo-meta-description-fix-2026-09-17/zenith-seo-meta-description-fix-2026-09-17.tar.gz" meta.tar.gz 52752770f3c0247a826cbc294038831ed43b0e6269c0ae847e9210d194caf775
tar -xzf "$zenith_build_tmp/meta.tar.gz"
zenith_download "$zenith_release_base/ai-visibility-foundation-2026-09-18/zenith-ai-visibility-foundation-2026-09-17.tar.gz" visibility.tar.gz bee472df33433111427df400def241621d6d2cb788b861dd49b9bb32627d3fe8
tar -xzf "$zenith_build_tmp/visibility.tar.gz"
zenith_download "$zenith_release_base/bing-entity-verification-2026-09-18/zenith-bing-entity-verification-2026-09-18.tar.gz" bing.tar.gz db83266460aa90a9b9133220d15b723d9aa874ef01ab2aa76fade7cfbc915f9d
tar -xzf "$zenith_build_tmp/bing.tar.gz"
zenith_download "$zenith_release_base/ai-entity-trust-2026-09-18/zenith-ai-entity-trust-2026-09-18.tar.gz" entity.tar.gz fae288976ba23bf550cfc8b638cd69f6cd9abe8bd212bdab9bc63ed781827a4b
tar -xzf "$zenith_build_tmp/entity.tar.gz"
zenith_download "$zenith_release_base/export-readiness-2026-09-21/zenith-export-overlay-2026-09-21.tar.gz" export.tar.gz 2a0343e7ec6a226c6896bea34982255d8d72ba69c1101807abcb273ff453ef4b
tar -xzf "$zenith_build_tmp/export.tar.gz"
zenith_download "https://raw.githubusercontent.com/cenktepegoz/zenith-porcelain-render-test/25063eb75ed173ed5e54f137a4cb2141796bdb59/zenith-local-regions-2026-09-21.tar.gz" regions.tar.gz 365a9698285f74cd89d00cc5f539c240c52f15a288b1cb522c04f9f4992e113b
mkdir "$zenith_build_tmp/regions"
tar -xzf "$zenith_build_tmp/regions.tar.gz" -C "$zenith_build_tmp/regions"
cp "$zenith_build_tmp/regions/app/region-data.ts" app/region-data.ts
cp "$zenith_build_tmp/regions/app/region-pages.css" app/region-pages.css
cp "$zenith_build_tmp/regions/app/components/region-page.tsx" app/components/region-page.tsx
mkdir -p 'app/bolge/[slug]'
cp "$zenith_build_tmp/regions/app/bolge/page.tsx" app/bolge/page.tsx
cp "$zenith_build_tmp/regions/app/bolge/[slug]/page.tsx" 'app/bolge/[slug]/page.tsx'
node -e 'const fs = require('"'"'node:fs'"'"'); function replaceOnce(file, before, after) { const source = fs.readFileSync(file, '"'"'utf8'"'"'); if (source.split(before).length !== 2) throw new Error(`Unexpected source in ${file}; refusing an unsafe merge`); fs.writeFileSync(file, source.replace(before, after)); } replaceOnce('"'"'app/layout.tsx'"'"', '"'"'import "./knowledge-editorial.css";'"'"', '"'"'import "./knowledge-editorial.css";\nimport "./region-pages.css";\nimport { locationSchema } from "./location-schema";\nimport { regions } from "./region-data";'"'"'); replaceOnce('"'"'app/layout.tsx'"'"', '"'"'  areaServed: ['"'"', '"'"'  location: locationSchema["@graph"].map((location) => ({ "@id": location["@id"] })),\n  areaServed: [\n    ...regions.map(({ city }) => ({ "@type": "City", name: city })),'"'"'); replaceOnce('"'"'app/layout.tsx'"'"', '"'"'JSON.stringify(organizationSchema)'"'"', '"'"'JSON.stringify({ "@context": "https://schema.org", "@graph": [organizationSchema, ...locationSchema["@graph"]] })'"'"'); replaceOnce('"'"'app/components/footer.tsx'"'"', '"'"'<a href="/kurumsal-profil">Kurumsal Profil</a>'"'"', '"'"'<a href="/kurumsal-profil">Kurumsal Profil</a><a href="/bolge">Hizmet Bölgeleri</a>'"'"'); replaceOnce('"'"'app/sitemap.ts'"'"', "import { exportPages } from '"'"'./english-export-data'"'"';", "import { exportPages } from '"'"'./english-export-data'"'"';\nimport { regions } from '"'"'./region-data'"'"';"); replaceOnce('"'"'app/sitemap.ts'"'"', '"'"'    ...knowledgeArticles.map('"'"', '"'"'    ...["/bolge", ...regions.map(({ slug }) => `/bolge/${slug}`)].map((path) => ({ url: `${base}${path}`, lastModified: new Date("2026-09-21"), changeFrequency: "monthly" as const, priority: .8 })),\n    ...knowledgeArticles.map('"'"'); replaceOnce('"'"'app/cozumler/[slug]/page.tsx'"'"', '"'"'    <section className="application-band">'"'"', '"'"'    {slug === "mutfak-tezgahlari" && <section className="related-guide section-shell"><a href="/bolge"><div><p className="eyebrow">Bölgesel proje planı</p><h2>Ankara, Bursa, Eskişehir ve Kütahya hizmet kapsamını inceleyin.</h2></div><span>Hizmet bölgelerini açın ↗</span></a></section>}\n    <section className="application-band">'"'"'); console.log('"'"'Export and local-region integration: 4 shared files merged successfully.'"'"');'
node <<'ZENITH_BRANDS_NODE'
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const sha = value => crypto.createHash('sha256').update(value).digest('hex');
const payload = Buffer.from('', 'base64');
if (sha(payload) !== '1336d174bc2be7f1034194a560d4effd342b41aed6a25eb80a700b4d82cf8a37') throw new Error('Brand package checksum mismatch');
const entries = JSON.parse(require('node:zlib').gunzipSync(payload));
for (const entry of entries) {
  if (!entry.path.startsWith('app/') || entry.path.split('/').includes('..') || sha(entry.content) !== entry.after) throw new Error('Invalid brand entry');
  const actual = fs.existsSync(entry.path) ? sha(fs.readFileSync(entry.path)) : null;
  if (actual !== entry.before && actual !== entry.after) throw new Error('Baseline changed; refusing to overwrite: ' + entry.path);
}
for (const entry of entries) {
  fs.mkdirSync(path.dirname(entry.path), {recursive: true});
  fs.writeFileSync(entry.path, entry.content);
}
console.log('Verified brand library: ' + entries.length + ' application files applied.');
ZENITH_BRANDS_NODE
if [ "${1:-}" = '--prepare-only' ]; then exit 0; fi
corepack pnpm install --frozen-lockfile
corepack pnpm build
